#include <stdio.h>
#include <string.h>

int main(void) {
    int a = 1, b = 2;

    const int *pc = &a;        /* pointer to const int */
    /* *pc = 5;                   error: assignment of read-only location */
    pc = &b;                   /* ok: repoint */

    int *const cp = &a;        /* const pointer to int */
    *cp = 5;                   /* ok: a is now 5 */
    /* cp = &b;                   error: assignment of read-only variable */

    const int *const cc = &a;  /* neither can change through cc */
    (void)cc;

    const int k = 10;          /* may live in .rodata */
    int *evil = (int *)&k;     /* cast away const */
    /* *evil = 7;                 undefined behaviour: may crash or be ignored */
    (void)evil;

    printf("%d %d %zu\n", a, *pc, strlen("hi"));
    return 0;
}

size_t count_char(const char *s, char c) {
    size_t n = 0;
    for (; *s; s++) n += (*s == c);
    return n;
}
const char *lit = "banana";   /* literal passes without a cast */
size_t k = count_char(lit, 'a');

